import {find,isLocked,clone} from '../document/model.js';
import {evaluated,setProperty,enableTrack} from '../animation/evaluate.js';
import {escape} from '../renderer/svg.js';
import {shadowFields,shadowDefaults} from '../scene/shadow.js';
import {setInspector} from './workspace.js';
import {showGraph} from '../timeline/graph.js';
const sessions=new WeakMap();
export function validShadowValue(prop,value){if(prop==='shadowEnabled')return typeof value==='boolean';if(prop==='shadowColor')return /^#[0-9a-f]{6}$/i.test(value);const bounds=prop==='shadowOpacity'?[0,1]:prop==='shadowBlur'?[0,200]:[-4096,4096];return Object.hasOwn(shadowFields,prop)&&Number.isFinite(value)&&value>=bounds[0]&&value<=bounds[1];}
export class ShadowPreviewSession{
 constructor(a,id){this.a=a;this.id=id;this.dirty=new Set();this.closed=false;this.time=a.time;this.values=this.read();a.appearancePreview??=new Map();}
 read(){const n=find(this.a.doc,this.id);if(!n)return {...shadowDefaults};const v=evaluated(n,this.a.time);return Object.fromEntries(Object.keys(shadowDefaults).map(prop=>[prop,clone(v[prop]??shadowDefaults[prop])]));}
 set(prop,value){if(this.closed||!find(this.a.doc,this.id)||!validShadowValue(prop,value)||isLocked(this.a.doc,this.id))return false;this.values[prop]=value;this.dirty.add(prop);if(prop!=='shadowEnabled'){this.values.shadowEnabled=true;this.dirty.add('shadowEnabled');}this.a.appearancePreview.set(this.id,{...this.a.appearancePreview.get(this.id),...clone(this.values)});return true;}
 refresh(){if(this.closed)return;if(!find(this.a.doc,this.id)){this.cancel();return;}if(!this.dirty.size&&this.time!==this.a.time){this.time=this.a.time;this.values=this.read();}}
 finish(){const remaining={...this.a.appearancePreview.get(this.id)};for(const prop of Object.keys(shadowDefaults))delete remaining[prop];if(Object.keys(remaining).length)this.a.appearancePreview.set(this.id,remaining);else this.a.appearancePreview.delete(this.id);this.closed=true;}
 cancel(){if(this.closed)return;this.finish();this.a.renderStage();}
 apply(animate=false){if(this.closed)return false;const n=find(this.a.doc,this.id);if(!n||isLocked(this.a.doc,this.id)){this.cancel();return false;}const values=clone(this.values),dirty=[...this.dirty];this.finish();if(dirty.length||animate)this.a.mutate(animate?'Animate shadow':'Drop shadow',()=>{if(dirty.includes('shadowEnabled')||animate)n.shadowEnabled=animate?true:values.shadowEnabled;for(const prop of Object.keys(shadowFields)){if(animate){enableTrack(n,prop,this.a.time,this.a.ease);setProperty(n,prop,values[prop],this.a.time);}else if(dirty.includes(prop))setProperty(n,prop,values[prop],this.a.time);}});else this.a.renderStage();return true;}
}
export function refreshShadowEditor(a){const entry=sessions.get(a);if(!entry)return;entry.session.refresh();if(entry.session.closed){entry.dialog.close();return;}entry.sync();}
export function showLayerMenu(a,id=a.selected[0]){
 const n=find(a.doc,id);if(!n)return a.toast('Select a layer first.');const previous=sessions.get(a);previous?.session.cancel();previous?.dialog.close();document.querySelector('#shadow-editor')?.close();a.pause();a.properties.flush();a.selected=[id];a.render();
 const d=document.createElement('dialog');d.id='shadow-editor';d.className='shadow-editor';d.dataset.modal='false';d.setAttribute('aria-labelledby','shadow-editor-title');document.body.append(d);
 const heading=`<header><strong id="shadow-editor-title">${n.reference?'Reference':n.type==='group'?'Group':'Drop shadow'} · ${escape(n.name)}</strong><button data-shadow-cancel aria-label="Close shadow editor">×</button></header>`;
 const navigation='<nav><button data-layer-graph>Graph</button><button data-layer-properties>Properties</button></nav>';
 if(n.reference||n.type==='group'){d.innerHTML=heading+navigation+(n.reference?`<label class="shadow-preview-switch"><input data-reference-export type="checkbox" ${n.exportIncluded?'checked':''}> Include reference in exports</label><label>Reference opacity<input data-reference-opacity type="range" min=".05" max="1" step=".05" value="${n.opacity}"></label><p>Reference frames are locked for tracing. Trim them in the sequencer.</p>`:'<p>Select a shape inside this group to add its shadow.</p>');d.querySelector('[data-reference-export]')?.addEventListener('change',e=>a.mutate('Reference export visibility',()=>n.exportIncluded=e.target.checked));d.querySelector('[data-reference-opacity]')?.addEventListener('change',e=>a.mutate('Reference opacity',()=>n.opacity=Number(e.target.value)));}
 else{
  const session=new ShadowPreviewSession(a,id),locked=isLocked(a.doc,id),v=session.values;
  const field=(prop,label)=>{const offset=prop==='shadowX'||prop==='shadowY',min=offset?-4096:0,max=prop==='shadowOpacity'?1:prop==='shadowBlur'?200:4096,step=prop==='shadowOpacity'?.01:1;return `<label class="shadow-control"><span>${label}</span>${prop==='shadowColor'?`<input data-shadow-value="${prop}" type="color" value="${v[prop]}" aria-label="${label}">`:`<input data-shadow-value="${prop}" type="number" min="${min}" max="${max}" step="${step}" value="${v[prop]}" aria-label="${label}"><input data-shadow-slider="${prop}" type="range" min="${offset?-200:min}" max="${offset?200:max}" step="${step}" value="${v[prop]}" aria-label="${label} slider">`}</label>`;};
  d.innerHTML=heading+navigation+`<fieldset ${locked?'disabled':''}><label class="shadow-preview-switch"><input data-shadow-enabled type="checkbox" ${v.shadowEnabled?'checked':''}> Preview shadow</label><div class="shadow-controls">${Object.entries(shadowFields).map(([prop,label])=>field(prop,label)).join('')}</div><div class="shadow-offset-pad" tabindex="0" role="slider" aria-valuemin="-4096" aria-valuemax="4096" aria-valuenow="12" aria-label="Shadow offset: drag or use arrow keys"><span aria-hidden="true">+</span><i aria-hidden="true"></i></div><p class="shadow-help">Drag the pad to move the shadow. Adjusting a control turns Preview on.</p><output class="shadow-status"></output><footer><button data-shadow-animate>Animate</button><button data-shadow-cancel>Cancel</button><button data-shadow-apply class="primary">Apply</button></footer></fieldset>`;
  if(locked)d.insertAdjacentHTML('beforeend','<p>Unlock this layer to edit its shadow.</p>');
  let scheduled=0;const preview=()=>{if(scheduled)return;scheduled=requestAnimationFrame(()=>{scheduled=0;if(!session.closed)a.renderStage();});};
  const pad=d.querySelector('.shadow-offset-pad');const sync=()=>{const values=session.values;d.querySelector('[data-shadow-enabled]').checked=!!values.shadowEnabled;for(const prop of Object.keys(shadowFields)){const input=d.querySelector(`[data-shadow-value="${prop}"]`),slider=d.querySelector(`[data-shadow-slider="${prop}"]`);if(document.activeElement!==input)input.value=values[prop];if(slider){if(values[prop]<Number(slider.min))slider.min=values[prop];if(values[prop]>Number(slider.max))slider.max=values[prop];slider.value=values[prop];}}pad.setAttribute('aria-valuenow',String(values.shadowX));pad.setAttribute('aria-valuetext',`Horizontal ${values.shadowX} pixels, vertical ${values.shadowY} pixels`);pad.querySelector('i').style.transform=`translate(${Math.max(-45,Math.min(45,values.shadowX/4))}px,${Math.max(-35,Math.min(35,values.shadowY/4))}px)`;d.querySelector('.shadow-status').textContent=`${values.shadowEnabled?'Preview on':'Preview off'} · Apply at frame ${Math.round(a.time*a.doc.fps)}`;};
  d.addEventListener('input',e=>{if(locked)return;const prop=e.target.dataset.shadowValue||e.target.dataset.shadowSlider;if(prop&&session.set(prop,prop==='shadowColor'?e.target.value:Number(e.target.value))){sync();preview();}else if(e.target.hasAttribute('data-shadow-enabled')&&session.set('shadowEnabled',e.target.checked)){sync();preview();}});
  let gesture;pad.onpointerdown=e=>{if(locked||e.button!==0)return;e.preventDefault();pad.setPointerCapture(e.pointerId);gesture={id:e.pointerId,x:e.clientX,y:e.clientY,offsetX:session.values.shadowX,offsetY:session.values.shadowY};};pad.onpointermove=e=>{if(!gesture||gesture.id!==e.pointerId)return;session.set('shadowX',Math.max(-4096,Math.min(4096,Math.round(gesture.offsetX+(e.clientX-gesture.x)*2))));session.set('shadowY',Math.max(-4096,Math.min(4096,Math.round(gesture.offsetY+(e.clientY-gesture.y)*2))));sync();preview();};pad.onpointerup=pad.onpointercancel=e=>{if(gesture?.id===e.pointerId)gesture=null;};pad.onkeydown=e=>{const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!delta||locked)return;e.preventDefault();const step=e.shiftKey?10:1;session.set('shadowX',Math.max(-4096,Math.min(4096,session.values.shadowX+delta[0]*step)));session.set('shadowY',Math.max(-4096,Math.min(4096,session.values.shadowY+delta[1]*step)));sync();preview();};
  const apply=animate=>{const invalid=[...d.querySelectorAll('input')].find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();return;}if(scheduled){cancelAnimationFrame(scheduled);scheduled=0;}if(session.apply(animate)){d.close();if(animate)showGraph(a,id,'shadowX');}};d.querySelector('[data-shadow-apply]').onclick=()=>a.safe(()=>apply(false));d.querySelector('[data-shadow-animate]').onclick=()=>a.safe(()=>apply(true));sessions.set(a,{session,dialog:d,sync});d.addEventListener('close',()=>{if(scheduled)cancelAnimationFrame(scheduled);session.cancel();if(sessions.get(a)?.dialog===d)sessions.delete(a);},{once:true});sync();
 }
 d.querySelectorAll('[data-shadow-cancel]').forEach(button=>button.onclick=()=>d.close());d.querySelector('[data-layer-graph]').onclick=()=>{d.close();showGraph(a,id);};d.querySelector('[data-layer-properties]').onclick=()=>{d.close();setInspector(a,true);};d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();d.close();}});d.addEventListener('close',()=>d.remove(),{once:true});d.show();return d;
}
